-- Month Health: letters 1–8 — two-action CTA + GetCourse lesson buttons.

-- Letter 1
update public.email_automation_steps
set
  html_body = replace(replace(html_body, 'Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке «День». ', ''), '<p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">Урок ждёт вас в Гармонизаторе, на вкладке «День».</p>', '<p>Нажмите кнопку ниже, чтобы открыть первый (вводный) урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 1</a></p><p></p>'),
  html_body_i18n = jsonb_set(html_body_i18n, '{ru}', to_jsonb(replace(replace(html_body_i18n->>'ru', 'Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке «День». ', ''), '<p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">Урок ждёт вас в Гармонизаторе, на вкладке «День».</p>', '<p>Нажмите кнопку ниже, чтобы открыть первый (вводный) урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 1</a></p><p></p>'))),
  blocks_i18n = jsonb_set(blocks_i18n, '{ru}', (
      select jsonb_agg(case when elem->>'id' = 'month-health-01-text' then jsonb_set(elem, '{html}', to_jsonb(replace(replace(elem->>'html', 'Первый (вводный) урок уже доступен вам в Гармонизаторе на вкладке «День». ', ''), '<p style="margin:0;padding:0;word-break:break-word;overflow-wrap:anywhere;word-break:break-word;overflow-wrap:anywhere;font-size:16px !important;line-height:24px;font-family:Arial,Helvetica,sans-serif;">Урок ждёт вас в Гармонизаторе, на вкладке «День».</p>', '<p>Нажмите кнопку ниже, чтобы открыть первый (вводный) урок в браузере, или посмотрите его в Гармонизаторе на вкладке «День».</p><p></p><p style="text-align:center"><a href="{{course_lesson_url}}" target="_blank" style="border-style:solid;border-color:#569c19;border-width:6px 20px;display:inline-block;border-radius:4px;font-size:18px;font-family:Helvetica,Arial,sans-serif;font-weight:normal;color:#ffffff;text-decoration:none;background:#569c19;mso-line-height-rule:exactly">Открыть урок 1</a></p><p></p>'))) else elem end order by ord)
